namespace sv_449fcfab133a4847b9a11cc6e1274955.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Registered as Scoped so each Blazor Server circuit (user session) gets its own instance.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new("WH-001", "Warehouse A — East"),
        new("WH-002", "Warehouse B — West"),
        new("WH-003", "Warehouse C — Central"),
        new("WH-004", "Warehouse D — North"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    /// <summary>
    /// Raised on the calling thread whenever the selected warehouse changes.
    /// Subscribers must call InvokeAsync/StateHasChanged on their own synchronization context.
    /// </summary>
    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public sealed record WarehouseInfo(string Id, string Name);

namespace sv_449fcfab133a4847b9a11cc6e1274955.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all
/// subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random s_random = new();

    private int _lastLowStockCount;

    /// <summary>
    /// The most recently fetched low-stock count, cached so components that
    /// subscribe late can read the latest value immediately.
    /// </summary>
    public int LastLowStockCount => _lastLowStockCount;

    /// <summary>
    /// Raised whenever fresh alert data is available.
    /// All subscribed components should re-render when this fires.
    /// </summary>
    public event Action? OnAlertDataChanged;

    /// <summary>
    /// Simulates a database query that returns the number of items below
    /// minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async DB call with random result 0–15
        var count = s_random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by the polling component after fetching new data.
    /// Stores the count and notifies every subscriber.
    /// </summary>
    public void PublishNewCount(int count)
    {
        _lastLowStockCount = count;
        OnAlertDataChanged?.Invoke();
    }
}

