@rendermode InteractiveServer
@using sv_449fcfab133a4847b9a11cc6e1274955.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">
            <strong>@WarehouseState.CurrentWarehouseName</strong>
            <span class="text-muted ms-2">(@WarehouseState.CurrentWarehouseId)</span>
        </p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            <AlertBadge @rendermode="InteractiveServer" />
        </h5>
        <p class="card-text">
            @if (_isPolling)
            {
                <span class="text-success">● Polling active — refreshing every 10 seconds</span>
            }
            else
            {
                <span class="text-muted">○ Polling inactive</span>
            }
        </p>
        <p class="card-text fs-4">
            Items below minimum level: <strong>@AlertService.LastLowStockCount</strong>
        </p>
        <p class="text-muted small">
            Last checked: @_lastChecked?.ToString("HH:mm:ss") ?? "—"
        </p>
    </div>
</div>

@code {
    private System.Threading.Timer? _pollingTimer;
    private bool _isPolling;
    private DateTime? _lastChecked;
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Perform an initial poll immediately, then start the 10-second timer
            await PollAsync();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _pollingTimer = new System.Threading.Timer(
            async _ => await PollAsync(),
            null,
            TimeSpan.FromSeconds(10),
            TimeSpan.FromSeconds(10));
        _isPolling = true;
    }

    private async Task PollAsync()
    {
        try
        {
            var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
            _lastChecked = DateTime.Now;
            // Publish to ALL subscribers (sidebar badge, this page, etc.)
            AlertService.PublishNewCount(count);
        }
        catch (ObjectDisposedException)
        {
            // Component was disposed during async work — ignore
        }
    }

    private void HandleWarehouseChanged()
    {
        // When the warehouse changes, poll immediately for the new warehouse's data
        _ = InvokeAsync(async () =>
        {
            await PollAsync();
            StateHasChanged();
        });
    }

    private void HandleAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        _pollingTimer?.Dispose();
        _cts?.Cancel();
        _cts?.Dispose();
        _isPolling = false;
    }
}

